package br.edu.ifrn.sistemachamados.dto.response; import org.springframework.data.domain.Page; import java.util.*; import java.util.function.*; public record PageResponse<T>(List<T> content,int page,int size,long totalElements,int totalPages){public static <E,T> PageResponse<T> of(Page<E> p,Function<E,T> f){return new PageResponse<>(p.map(f).getContent(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}}
